good.code:
const key = (id: string) => `product:v3:${id}`
const ttl = () => Math.round(300 * (0.9 + Math.random() * 0.2)) // 270-330 s

async function getProduct(id: string) {
  const hit = await cache.get(key(id))
  if (hit) return JSON.parse(hit)
  const row = await singleFlight(key(id), () => db.products.find(id))
  if (row) await cache.set(key(id), JSON.stringify(row), { ex: ttl() })
  return row
}

async function updateProduct(id: string, patch: Patch) {
  await db.products.update(id, patch) // commit first
  await cache.del(key(id))            // next read reloads the truth
}

